INSERT INTO events (id, title, description, date, time, location, type, capacity, registered_count, is_active, created_at, updated_at) VALUES
  ('670c1d2e3f4a5b6c7d8e9f01', 'Global Boldness Conference', 'A gathering of unashamed believers worldwide.', '2026-12-15T09:00:00.000Z', '9:00 AM', 'Lagos, Nigeria', 'conference', 500, 0, 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('670c1d2e3f4a5b6c7d8e9f02', 'Street Preaching Workshop', 'Hands-on training for open-air evangelism.', '2027-01-20T14:00:00.000Z', '2:00 PM', 'London, UK', 'workshop', 80, 0, 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('670c1d2e3f4a5b6c7d8e9f03', 'Campus Outreach Day', 'University campuses across 16 nations.', '2026-10-30T10:00:00.000Z', '10:00 AM', 'Multiple Cities', 'outreach', 0, 0, 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('670c1d2e3f4a5b6c7d8e9f04', 'Unashamed Online Prayer', 'Weekly prayer and testimony stream.', '2026-12-22T19:00:00.000Z', '7:00 PM', 'Zoom', 'online', 1000, 0, 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
INSERT INTO testimonies (id, name, location, text, category, is_approved, is_featured, created_at, updated_at) VALUES
  ('680d1e2f3a4b5c6d7e8f9a01', 'Shiloh', 'Eswatini', 'Today something remarkable happened. After I shared the gospel (open air) I went up to a group of people that had been standing beside me listening from a distance and shared the gospel with them. Amongst the group was a man who seemed as though he was really listening. Later on I went up to him and shared the gospel with him one on one. After sharing with him and asking if he would want to receive Jesus as his saviour he said "wait come follow me". He led me to a salon and told me to share with them what I had shared with him. When I was done, all at once in that salon I led 18+ people in the prayer of salvation including the man himself.', 'Evangelism', 1, 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a02', 'Afe Okojie', 'Nigeria', 'For the longest time, most of my Christian life had been spent sheltered and living religiously. When I first came across @__thetimeisnow, something in me had woken up, it was like a veil lifted from my eyes and I remembered why I was really here. I have won more souls after coming across The Time Is Now than I have ever won in my entire life. I and my friends started preaching from dorm to dorm, room to room. We preached in 594 rooms, winning over 150 souls to Christ.', 'Evangelism', 1, 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a03', 'Favour Salami', 'UK', 'I wanted to let you know that today I preached on the train, and honestly thank you to your page The Time Is Now. All of your videos broke it down and highlighted how easy and important it is to preach open air. I was so nervous, and I don''t typically get nervous, but it was so easy. You spend so much time fixated on how nervous you feel but when you do it — BAM, that''s it. Looking back I should''ve said more, but I did it.', 'Evangelism', 1, 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a04', 'Chibuikem', 'Canada', 'This morning, I woke up and went straight to my knees in tears with a deep hunger to see change in my environment — to see people love Jesus. Today, I preached open air for the first time at YorkU! This is something that has beeeen on my heart. Now that I''ve done it, I honestly want to do it again. I''m so grateful to the Lord that He would think of me and trust me with this vision to spread the gospel.', 'Evangelism', 1, 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a05', 'Selam', 'USA', 'I DID IT! I finally preached on the plane! Flying out of Portland, OR, I honestly expected objections but to my surprise, everyone listened quietly until I finished. Even more touching, at the gate a woman waited just to tell me how happy she was that a woman stood up to share about God. She said she loves God, and that really blessed me.', 'Evangelism', 1, 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a06', 'Beverly', 'USA', 'It just happened to me while getting ready to preach on the plane. I saw your post right before and did it anyways! I ran out of storage while recording but half the plane literally started clapping at the end and even though I''ve preached in multiple planes, trains and places before, this is the first time I could audibly hear people saying the prayer of salvation after me. A few came up to tell me that was very brave and encouraging for them. Praise God!', 'Evangelism', 1, 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a07', 'Joselyn', 'Nigeria', 'Today I preached in 3 buses on the way to work. It takes 2-3 buses to get to work, and usually I preach in the one with the longest ride, cause that''s when I''m able to muster up enough courage. But I''m glad that I was able to preach in all three today. The beautiful thing is when I preached in the first and second, the third one was easier for me and in all the buses, the people were very receptive.', 'Lifestyle', 1, 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a08', 'Precious', 'Canada', 'I joined the uber challenges and I am in tears right now. I just finished preaching to an uber driver and the Holy Spirit was heavily present! He told me he goes to church now and then, I just shared Jesus with him and we prayed after. He kept telling me thank you and that goosebumps came over his body and he started crying and that he felt Jesus press on his soul as I preached.', 'Lifestyle', 1, 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a09', 'Sarah', 'UK', 'A friend challenged me to preach on our flight, something I had never done before. During the hour-long flight, my mind wrestled with the challenge. Then I prayed in tongues, and instantly my heart was settled. When I stood up, the words just flowed. The entire plane listened, and some even clapped at the end.', 'Evangelism', 1, 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('680d1e2f3a4b5c6d7e8f9a0a', 'Michael T.', 'United States', 'One of the souls I preached to from the Unashamed Challenge went to Church today. He previously said he won''t go back to Church because he felt like God disappointed him — but this has encouraged me. I''m so glad I preached to him that day.', 'Workplace', 1, 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
INSERT INTO site_content (id, key, title, content, type, metadata, created_at, updated_at) VALUES
  ('690e1f2a3b4c5d6e7f8a9b01', 'hero', 'THE TIME IS NOW', 'Making radical Christianity normal again.', 'hero', '{"kicker":"A movement of unashamed believers","blurb":"“Is your comfort zone more important than someone else’s eternity?”"}', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('690e1f2a3b4c5d6e7f8a9b02', 'about', 'About Us', 'The Time is Now is a movement designed to awaken believers from passivity to consistently preach the gospel with boldness and urgency in this generation thereby causing them to live up to their full potential in Christ.', 'about', '{}', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('690e1f2a3b4c5d6e7f8a9b03', 'mission', 'Our Mission', 'Our mission is simple: make radical Christianity normal again.', 'mission', '{}', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('690e1f2a3b4c5d6e7f8a9b04', 'featured', 'Featured', 'Highlighted content and calls to action.', 'featured', '{}', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
INSERT INTO site_settings (id, allow_registration, pay_paypal, updated_at) VALUES (1, 1, 1, '2026-01-01T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET allow_registration = excluded.allow_registration, pay_paypal = excluded.pay_paypal, updated_at = excluded.updated_at;
